WITH recent_store_sales AS (SELECT * FROM store_sales WHERE store_id IN (1, 5, 6) OR product_id IN (2, 3, 10)), store_sales_stats AS (SELECT DATE_TRUNC('MONTH', sale_date) AS sale_month, MAX(units) - MIN(units) AS units_range, COUNT(units) AS units_count FROM recent_store_sales GROUP BY DATE_TRUNC('MONTH', sale_date)) SELECT * FROM store_sales_stats ORDER BY units_count DESC, units_range DESC;
